parts.text:
{
  "units": [
    {
      "quote": "29 CFR 825.110 — Eligible employee.",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Title heading for 29 CFR 825.110 designating the regulation governing eligible employees, possessing no substantive legal requirement on its own."
    },
    {
      "quote": "An eligible employee is an employee of a covered employer who:\n\n(1) Has been employed by the employer for at least 12 months, and\n(2) Has been employed for at least 1,250 hours of service during the 12-month period immediately preceding the commencement of the leave ( see § 825.801 for special hours of service requirements for airline flight crew employees), and\n(3) Is employed at a worksite where 50 or more employees are employed by the employer within 75 miles of that worksite. See § 825.105(b) regarding employees who work outside the U.S.",
      "scope_quotes": [
        "(a) An eligible employee is an employee of a covered employer who:"
      ],
      "kind": "definition",
      "meaning": "To be an eligible employee under the FMLA, an employee of a covered employer must meet three cumulative criteria: have been employed by that employer for at least 12 months; have been employed for at least 1,250 hours of service during the 12-month period immediately preceding the start of the leave (subject to special rules in § 825.801 for airline flight crew employees); and be employed at a worksite where 50 or more employees are employed by the employer within 75 miles of that worksite (referencing § 825.105(b) for employees outside the U.S.)."
    },
    {
      "quote": "The 12 months an employee must have been employed by the employer need not be consecutive months, provided",
      "scope_quotes": [
        "(b) The 12 months an employee must have been employed by the employer need not be consecutive months, provided"
      ],
      "kind": "permission",
      "meaning": "The 12 months of employment required for FMLA eligibility do not have to be consecutive, provided the governing conditions and rules regarding breaks in service under paragraph (b) are met."
    },
    {
      "quote": "Subject to the exceptions provided in paragraph (b)(2) of this section, employment periods prior to a break in service of seven years or more need not be counted in determining whether the employee has been employed by the employer for at least 12 months.",
      "scope_quotes": [
        "(b) The 12 months an employee must have been employed by the employer need not be consecutive months, provided",
        "(1) Subject to the exceptions provided in paragraph (b)(2) of this section,"
      ],
      "kind": "permission",
      "meaning": "When determining whether an employee has been employed for at least 12 months, employers are not required to count employment periods occurring prior to a break in service of seven years or more, unless one of the exceptions in paragraph (b)(2) applies."
    },
    {
      "quote": "Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed by the employer for at least 12 months where:\n\n(i) The employee's break in service is occasioned by the fulfillment of his or her Uniformed Services Employment and Reemployment Rights Act (USERRA), 38 U.S.C. 4301, et seq., covered service obligation. The period of absence from work due to or necessitated by USERRA-covered service must be also counted in determining whether the employee has been employed for at least 12 months by the employer. However, this section does not provide any greater entitlement to the employee than would be available under the USERRA; or",
      "scope_quotes": [
        "(2) Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed by the employer for at least 12 months where:"
      ],
      "kind": "requirement",
      "meaning": "Employment periods preceding a break in service of more than seven years must be counted toward the 12-month employment requirement if the break was occasioned by fulfilling a USERRA-covered service obligation; furthermore, the period of absence necessitated by USERRA service must also be counted, provided this does not confer greater entitlement than available under USERRA."
    },
    {
      "quote": "Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed by the employer for at least 12 months where:\n\n(ii) A written agreement, including a collective bargaining agreement, exists concerning the employer's intention to rehire the employee after the break in service (e.g., for purposes of the employee furthering his or her education or for childrearing purposes).",
      "scope_quotes": [
        "(2) Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed by the employer for at least 12 months where:"
      ],
      "kind": "requirement",
      "meaning": "Employment periods preceding a break in service of more than seven years must be counted toward the 12-month employment requirement if a written agreement (such as a collective bargaining agreement) exists expressing the employer's intention to rehire the employee after the break in service (for instance, to further education or for childrearing)."
    },
    {
      "quote": "If an employee is maintained on the payroll for any part of a week, including any periods of paid or unpaid leave (sick, vacation) during which other benefits or compensation are provided by the employer (e.g., workers' compensation, group health plan benefits, etc.), the week counts as a week of employment.",
      "scope_quotes": [
        "(3) If an employee is maintained on the payroll for any part of a week, including any periods of paid or unpaid leave (sick, vacation) during which other benefits or compensation are provided by the employer (e.g., workers' compensation, group health plan benefits, etc.), the week counts as a week of employment."
      ],
      "kind": "definition",
      "meaning": "A week is deemed to count as a week of employment toward the 12-month requirement if an employee is on the payroll for any part of that week, including periods of paid or unpaid leave (such as sick leave or vacation) in which the employer provides other benefits or compensation (such as workers' compensation or group health plan benefits)."
    },
    {
      "quote": "For purposes of determining whether intermittent/occasional/casual employment qualifies as at least 12 months, 52 weeks is deemed to be equal to 12 months.",
      "scope_quotes": [
        "(3)"
      ],
      "kind": "threshold",
      "meaning": "For intermittent, occasional, or casual employment, 52 weeks of qualifying employment is legally deemed to satisfy the 12 months of employment requirement."
    },
    {
      "quote": "Nothing in this section prevents employers from considering employment prior to a continuous break in service of more than seven years when determining whether an employee has met the 12-month employment requirement.",
      "scope_quotes": [
        "(4) Nothing in this section prevents employers from considering employment prior to a continuous break in service of more than seven years when determining whether an employee has met the 12-month employment requirement."
      ],
      "kind": "permission",
      "meaning": "Employers are permitted, at their discretion, to count employment that occurred prior to a continuous break in service exceeding seven years even when not required by paragraphs (b)(2)(i) or (b)(2)(ii)."
    },
    {
      "quote": "However, if an employer chooses to recognize such prior employment, the employer must do so uniformly, with respect to all employees with similar breaks in service.",
      "scope_quotes": [
        "(4) Nothing in this section prevents employers from considering employment prior to a continuous break in service of more than seven years when determining whether an employee has met the 12-month employment requirement."
      ],
      "kind": "requirement",
      "meaning": "If an employer exercises the option to credit employment prior to a break in service of more than seven years beyond statutory requirements, it must do so uniformly across all employees having similar breaks in service."
    },
    {
      "quote": "Except as provided in paragraph (c)(2) of this section and in § 825.801 containing the special hours of service requirement for airline flight crew employees, whether an employee has worked the minimum 1,250 hours of service is determined according to the principles established under the Fair Labor Standards Act (FLSA) for determining compensable hours of work. See 29 CFR part 785. The determining factor is the number of hours an employee has worked for the employer within the meaning of the FLSA.",
      "scope_quotes": [
        "(c)(1) Except as provided in paragraph (c)(2) of this section and in § 825.801 containing the special hours of service requirement for airline flight crew employees,"
      ],
      "kind": "requirement",
      "meaning": "Except as provided in paragraph (c)(2) and § 825.801 for airline flight crew employees, whether an employee satisfies the 1,250 hours of service threshold must be determined under FLSA principles for compensable hours worked (29 CFR part 785), with the determinative factor being the actual number of hours worked for the employer within the meaning of the FLSA."
    },
    {
      "quote": "The determination is not limited by methods of recordkeeping, or by compensation agreements that do not accurately reflect all of the hours an employee has worked for or been in service to the employer. Any accurate accounting of actual hours worked under FLSA's principles may be used.",
      "scope_quotes": [
        "(c)(1) Except as provided in paragraph (c)(2) of this section and in § 825.801 containing the special hours of service requirement for airline flight crew employees,"
      ],
      "kind": "permission",
      "meaning": "The calculation of compensable hours is not constrained by specific recordkeeping methods or inaccurate compensation agreements; any accurate accounting of actual hours worked under FLSA principles is permissible to establish hours of service."
    },
    {
      "quote": "An employee returning from USERRA-covered service shall be credited with the hours of service that would have been performed but for the period of absence from work due to or necessitated by USERRA-covered service in determining the employee's eligibility for FMLA-qualifying leave. Accordingly, a person reemployed following USERRA-covered service has the hours that would have been worked for the employer added to any hours actually worked during the previous 12-month period to meet the hours of service requirement.",
      "scope_quotes": [
        "(2)"
      ],
      "kind": "requirement",
      "meaning": "An employee returning from USERRA-covered service must be credited with the hours of service that would have been performed but for the military absence, which are added to actual hours worked during the previous 12 months to satisfy the 1,250-hour requirement (subject to § 825.801(c) for airline flight crews)."
    },
    {
      "quote": "In order to determine the hours that would have been worked during the period of absence from work due to or necessitated by USERRA-covered service, the employee's pre-service work schedule can generally be used for calculations. See § 825.801(c) for special rules applicable to airline flight crew employees.",
      "scope_quotes": [
        "(2)"
      ],
      "kind": "recommendation",
      "meaning": "To calculate the hours of service an employee would have worked during a USERRA-covered absence, the employer may generally use the employee's pre-service work schedule as the basis for the calculation, subject to special rules in § 825.801(c) for airline flight crews."
    },
    {
      "quote": "In the event an employer does not maintain an accurate record of hours worked by an employee, including for employees who are exempt from FLSA's requirement that a record be kept of their hours worked (e.g., bona fide executive, administrative, and professional employees as defined in FLSA Regulations, 29 CFR part 541), the employer has the burden of showing that the employee has not worked the requisite hours.",
      "scope_quotes": [
        "(3) In the event an employer does not maintain an accurate record of hours worked by an employee, including for employees who are exempt from FLSA's requirement that a record be kept of their hours worked (e.g., bona fide executive, administrative, and professional employees as defined in FLSA Regulations, 29 CFR part 541),"
      ],
      "kind": "requirement",
      "meaning": "If an employer fails to maintain accurate records of an employee's hours worked (including for FLSA-exempt executive, administrative, and professional employees under 29 CFR part 541), the burden of proof is on the employer to show that the employee has not worked the required 1,250 hours."
    },
    {
      "quote": "An employer must be able to clearly demonstrate, for example, that full-time teachers ( see § 825.102 for definition) of an elementary or secondary school system, or institution of higher education, or other educational establishment or institution (who often work outside the classroom or at their homes) did not work 1,250 hours during the previous 12 months in order to claim that the teachers are not eligible for FMLA leave. See § 825.801(d) for special rules applicable to airline flight crew employees.",
      "scope_quotes": [
        "(3) In the event an employer does not maintain an accurate record of hours worked by an employee, including for employees who are exempt from FLSA's requirement that a record be kept of their hours worked (e.g., bona fide executive, administrative, and professional employees as defined in FLSA Regulations, 29 CFR part 541),"
      ],
      "kind": "requirement",
      "meaning": "Where accurate hours records are not maintained, the employer must be able to clearly demonstrate that full-time teachers at an educational establishment did not work 1,250 hours in the prior 12 months in order to deny FMLA eligibility on hours grounds (subject to § 825.801(d) for airline flight crews)."
    },
    {
      "quote": "The determination of whether an employee meets the hours of service requirement and has been employed by the employer for a total of at least 12 months must be made as of the date the FMLA leave is to start.",
      "scope_quotes": [
        "(d) The determination of whether an employee meets the hours of service requirement and has been employed by the employer for a total of at least 12 months must be made as of the date the FMLA leave is to start."
      ],
      "kind": "requirement",
      "meaning": "The determination of whether an employee satisfies both the 12-month length of service and the 1,250 hours of service requirements must be evaluated as of the date the requested FMLA leave is scheduled to begin."
    },
    {
      "quote": "An employee may be on non-FMLA leave at the time he or she meets the 12-month eligibility requirement, and in that event, any portion of the leave taken for an FMLA-qualifying reason after the employee meets the eligibility requirement would be FMLA leave. See § 825.300(b) for rules governing the content of the eligibility notice given to employees.",
      "scope_quotes": [
        "(d)"
      ],
      "kind": "condition",
      "meaning": "If an employee is already on non-FMLA leave when reaching the 12-month employment threshold, any subsequent portion of the leave taken for an FMLA-qualifying reason after meeting that threshold becomes designated as FMLA leave."
    },
    {
      "quote": "Whether 50 employees are employed within 75 miles to ascertain an employee's eligibility for FMLA benefits is determined when the employee gives notice of the need for leave.",
      "scope_quotes": [
        "(e) Whether 50 employees are employed within 75 miles to ascertain an employee's eligibility for FMLA benefits is determined when the employee gives notice of the need for leave."
      ],
      "kind": "requirement",
      "meaning": "The requirement that 50 employees work within 75 miles of the employee's worksite must be assessed at the specific time the employee gives notice of the need for leave."
    },
    {
      "quote": "Whether the leave is to be taken at one time or on an intermittent or reduced leave schedule basis, once an employee is determined eligible in response to that notice of the need for leave, the employee's eligibility is not affected by any subsequent change in the number of employees employed at or within 75 miles of the employee's worksite, for that specific notice of the need for leave.",
      "scope_quotes": [
        "(e)"
      ],
      "kind": "statement",
      "meaning": "Regardless of whether leave is taken all at once or on an intermittent or reduced leave schedule, once an employee is determined eligible based on notice, subsequent decreases or increases in employee count within 75 miles cannot alter the employee's eligibility for that specific notice of need for leave."
    },
    {
      "quote": "Similarly, an employer may not terminate employee leave that has already started if the employee count drops below 50.",
      "scope_quotes": [
        "(e)"
      ],
      "kind": "prohibition",
      "meaning": "An employer is prohibited from terminating an employee's FMLA leave that has already commenced if the number of employees employed within 75 miles subsequently drops below 50."
    },
    {
      "quote": "For example, if an employer employs 60 employees in August, but expects that the number of employees will drop to 40 in December, the employer must grant FMLA benefits to an otherwise eligible employee who gives notice of the need for leave in August for a period of leave to begin in December.",
      "scope_quotes": [
        "(e) Whether 50 employees are employed within 75 miles to ascertain an employee's eligibility for FMLA benefits is determined when the employee gives notice of the need for leave."
      ],
      "kind": "requirement",
      "meaning": "Where an employer has 60 employees within 75 miles when notice is given in August, it must grant FMLA benefits to an otherwise eligible employee even if the employee count is expected to decrease to 40 when the leave begins in December."
    }
  ]
}
